var pinkShader = Shader.Find("Hidden/InternalErrorShader");
var results = new System.Collections.Generic.List<string>();
var matPaths = new System.Collections.Generic.HashSet<string>();
var shaderCounts = new System.Collections.Generic.Dictionary<string, int>();
int pinkCount = 0;
int totalRenderers = 0;

var renderers = UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsInactive.Include, FindObjectsSortMode.None);
foreach (var r in renderers)
{
    totalRenderers++;
    var mats = r.sharedMaterials;
    if (mats == null) continue;
    for (int i = 0; i < mats.Length; i++)
    {
        var m = mats[i];
        if (m == null)
        {
            results.Add($"NULL_MAT|{GetPath(r)}|{i}");
            pinkCount++;
            continue;
        }
        bool isPink = m.shader == null || m.shader.name == "Hidden/InternalErrorShader" || (pinkShader != null && m.shader == pinkShader);
        string sn = m.shader != null ? m.shader.name : "<null>";
        // Also flag common non-HDRP leftovers that often pink under HDRP
        bool urpLike = sn.StartsWith("Universal Render Pipeline/") || sn.StartsWith("Shader Graphs/") && sn.Contains("URP");
        bool builtinParticles = sn.StartsWith("Particles/") || sn == "Legacy Shaders/Particles/Additive" || sn.Contains("Mobile/Particles");
        if (isPink || urpLike)
        {
            string path = AssetDatabase.GetAssetPath(m);
            if (string.IsNullOrEmpty(path)) path = "(instance)";
            string key = path + "|" + sn;
            if (matPaths.Add(key))
            {
                results.Add($"{(isPink ? "PINK" : "URP")} | {path} | shader={sn} | usedBy={GetPath(r)}");
            }
            if (isPink) pinkCount++;
            if (!shaderCounts.ContainsKey(sn)) shaderCounts[sn] = 0;
            shaderCounts[sn]++;
        }
    }
}

