        string sn = m.shader.name;
        bool interest = sn.StartsWith("Legacy Shaders/Particles") || sn.StartsWith("Mobile/Particles") || sn.StartsWith("Hovl/") || sn.StartsWith("QFX/") || sn.StartsWith("WFX/") || sn.StartsWith("Particles/") || sn.StartsWith("Toon/") || sn.Contains("URP Water") || sn == "Shader Graphs/Water";
