    for (int i = 0; i < mats.Length; i++)
    {
        var m = mats[i];
        string sn = m == null ? "<null>" : (m.shader != null ? m.shader.name : "<nullshader>");
        bool bad = m == null || m.shader == null || sn == "Hidden/InternalErrorShader" || !m.shader.isSupported;
        bool speedTree = sn.IndexOf("SpeedTree", System.StringComparison.OrdinalIgnoreCase) >= 0;
        bool nature = sn.StartsWith("Nature/") || sn.StartsWith("Terrain/");
        bool urp = sn.StartsWith("Universal Render Pipeline/");
        if (!(bad || speedTree || nature || urp)) continue;
        string path = m != null ? AssetDatabase.GetAssetPath(m) : "";
        flagged.Add((bad?"BAD":"SUS") + " | " + GetPath(r) + " | mat=" + (m!=null?m.name:"NULL") + " | shader=" + sn + " | asset=" + path + " | pos=" + r.transform.position);
