// Broader pink hunt: magenta base colors, Gaia, SpeedTree, Builtin Standard on meshes that look mountainous
var sb = new System.Text.StringBuilder();
var renderers = UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsInactive.Include, FindObjectsSortMode.None);
int magentaish = 0;
var samples = new System.Collections.Generic.List<string>();
var shaderHits = new System.Collections.Generic.Dictionary<string,int>();
foreach (var r in renderers)
{
    var mats = r.sharedMaterials;
    if (mats == null) continue;
    for (int i=0;i<mats.Length;i++)
    {
        var m = mats[i];
        if (m == null) continue;
        string sn = m.shader != null ? m.shader.name : "<null>";
        if (!shaderHits.ContainsKey(sn)) shaderHits[sn]=0; shaderHits[sn]++;
        Color c = Color.black;
        bool hasC = false;
        if (m.HasProperty("_BaseColor")) { c = m.GetColor("_BaseColor"); hasC=true; }
        else if (m.HasProperty("_Color")) { c = m.GetColor("_Color"); hasC=true; }
        else if (m.HasProperty("_UnlitColor")) { c = m.GetColor("_UnlitColor"); hasC=true; }
        // Magenta error-ish: high R+B, low G
        bool mag = hasC && c.r > 0.8f && c.b > 0.8f && c.g < 0.35f && c.a > 0.05f;
        bool errorShader = sn == "Hidden/InternalErrorShader" || sn.Contains("Error");
        bool gaia = AssetDatabase.GetAssetPath(m).IndexOf("Gaia", System.StringComparison.OrdinalIgnoreCase)>=0 || r.gameObject.name.IndexOf("Gaia", System.StringComparison.OrdinalIgnoreCase)>=0 || GetPath(r).IndexOf("Gaia", System.StringComparison.OrdinalIgnoreCase)>=0;
        if (mag || errorShader)
        {
            magentaish++;
            if (samples.Count < 40)
                samples.Add((errorShader?"ERR":"MAG") + " | " + GetPath(r) + " | " + m.name + " | " + sn + " | col=" + c + " | active=" + r.gameObject.activeInHierarchy);
        }
        else if (gaia && samples.Count < 60 && sn.IndexOf("HDRP", System.StringComparison.OrdinalIgnoreCase)<0)
        {
            samples.Add("GAIA_NONHDRP | " + GetPath(r) + " | " + m.name + " | " + sn);
        }
    }
}
sb.AppendLine("magentaish=" + magentaish);
foreach (var s in samples) sb.AppendLine(s);

// Find large mesh renderers that might be mountains (bounds size)
var big = new System.Collections.Generic.List<string>();
foreach (var r in renderers)
{
    if (!r.gameObject.activeInHierarchy || !r.enabled) continue;
    var b = r.bounds;
    float size = b.size.magnitude;
    if (size < 50f) continue;
    var m0 = r.sharedMaterial;
    string sn = m0!=null && m0.shader!=null ? m0.shader.name : "null";
    big.Add("size=" + size.ToString("F1") + " | " + GetPath(r) + " | shader=" + sn + " | mat=" + (m0!=null?m0.name:"null") + " | center=" + b.center);
}
big.Sort();
big.Reverse();
sb.AppendLine("---BIG RENDERERS---");
for (int i=0;i<System.Math.Min(25,big.Count);i++) sb.AppendLine(big[i]);
return sb.ToString();

