foreach (var r in renderers)
{
  var mats = r.sharedMaterials;
  if (mats == null) continue;
  for (int i=0;i<mats.Length;i++)
  {
    if (mats[i] != null) continue;
    sb.AppendLine("NULL " + r.gameObject.name + " path=" + GetPath(r.transform) + " slot=" + i + " matCount=" + mats.Length);
    // Shopkeeper: try load from mesh importer materials
    if (r.gameObject.name.Contains("ShopKeeper") || GetPath(r.transform).Contains("ShopKeeper"))
    {
      var mf = r.GetComponent<MeshFilter>();
      string meshPath = mf != null && mf.sharedMesh != null ? AssetDatabase.GetAssetPath(mf.sharedMesh) : "";
      sb.AppendLine("  meshPath=" + meshPath);
      if (!string.IsNullOrEmpty(meshPath))
      {
        var assets = AssetDatabase.LoadAllAssetsAtPath(meshPath);
        Material found = null;
        foreach (var a in assets) if (a is Material mm) { found = mm; sb.AppendLine("  embeddedMat=" + mm.name + " shader=" + mm.shader.name); }
        if (found != null)
        {
          // Convert embedded if needed then assign
          if (found.shader != null && !found.shader.name.StartsWith("HDRP/") && (found.shader.name.StartsWith("Standard") || found.shader.name.StartsWith("Universal") || found.shader.name.StartsWith("Legacy")))
          {
             // Use lit convert for character
             var lit = Shader.Find("HDRP/Lit");
             var litMethod = auditor.GetMethod("ConvertToHdrpLit", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Static);
             if (litMethod != null && lit != null)
             {
               litMethod.Invoke(null, new object[] { found, lit });
               EditorUtility.SetDirty(found);
             }
          }
          mats[i] = found;
          r.sharedMaterials = mats;
          EditorUtility.SetDirty(r);
          PrefabUtility.RecordPrefabInstancePropertyModifications(r);
          sb.AppendLine("  assigned=" + found.name + " shader=" + found.shader.name);
        }
      }
    }
  }
}
