string GetPath(Transform t){var p=new System.Collections.Generic.List<string>();int d=0;while(t!=null&&d++<8){p.Add(t.name);t=t.parent;}p.Reverse();return string.Join("/",p);}

// Verify pulse scroll now binds _EmissiveColor on Brimmy / Plasma
var pulses = UnityEngine.Object.FindObjectsByType<MonoBehaviour>(FindObjectsInactive.Include, FindObjectsSortMode.None);
var sb = new System.Text.StringBuilder();
int checkedN = 0;
foreach (var mb in pulses)
{
  if (mb == null || mb.GetType().Name != "DMIMaterialPulseScroll") continue;
  var so = new SerializedObject(mb);
  if (!so.FindProperty("pulseEmission").boolValue) continue;
  mb.SendMessage("RebuildCaches", SendMessageOptions.DontRequireReceiver);
  var rProp = so.FindProperty("targetRenderer");
  Renderer r = rProp.objectReferenceValue as Renderer;
  if (r == null) r = mb.GetComponent<Renderer>();
  if (r == null || r.sharedMaterial == null) continue;
  var m = r.sharedMaterial;
  // Simulate bind preference
  bool hdrp = m.shader.name.StartsWith("HDRP/");
  string bind = "?";
  Color authored = Color.black;
  if (hdrp && m.HasProperty("_EmissiveColor")) { bind = "_EmissiveColor"; authored = m.GetColor("_EmissiveColor"); }
  else if (m.HasProperty("_EmissionColor")) { bind = "_EmissionColor"; authored = m.GetColor("_EmissionColor"); }
  sb.AppendLine(mb.name + " shader=" + m.shader.name + " bind=" + bind + " authored=" + authored + " baseMapST=" + m.HasProperty("_BaseColorMap_ST") + " emissiveMapST=" + m.HasProperty("_EmissiveColorMap_ST"));
  // Apply one pulse frame via reflection LateUpdate path — set MPB manually to verify
  var block = new MaterialPropertyBlock();
  r.GetPropertyBlock(block);
  if (bind == "_EmissiveColor")
  {
    Color pulsed = authored * 1.25f;
    block.SetColor("_EmissiveColor", pulsed);
    r.SetPropertyBlock(block);
    r.GetPropertyBlock(block);
    Color got = block.GetColor("_EmissiveColor");
    sb.AppendLine("  MPB write/read _EmissiveColor=" + got);
  }
  checkedN++;
  if (checkedN >= 5) break;
}
return sb.ToString();

