// Final inventory
int nulls=0, legacy=0, hovl=0, wfx=0, qfx=0, urp=0, pink=0;
var leftover = new System.Collections.Generic.HashSet<string>();
var renderers = UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsInactive.Include, FindObjectsSortMode.None);
foreach (var r in renderers) {
  var mats = r.sharedMaterials; if (mats==null) continue;
  foreach (var m in mats) {
    if (m==null) { nulls++; continue; }
    string sn = m.shader!=null?m.shader.name:"<null>";
    if (sn=="Hidden/InternalErrorShader") { pink++; leftover.Add("PINK "+AssetDatabase.GetAssetPath(m)); }
    if (sn.StartsWith("Universal Render Pipeline/")) { urp++; leftover.Add("URP "+AssetDatabase.GetAssetPath(m)); }
    if (sn.StartsWith("Legacy Shaders/Particles") || sn.StartsWith("Mobile/Particles") || sn.StartsWith("Particles/")) { legacy++; leftover.Add("LEGACY "+AssetDatabase.GetAssetPath(m)+" "+sn); }
    if (sn.StartsWith("Hovl/")) { hovl++; leftover.Add("HOVL "+AssetDatabase.GetAssetPath(m)+" "+sn); }
    if (sn.StartsWith("WFX/")) { wfx++; leftover.Add("WFX "+AssetDatabase.GetAssetPath(m)+" "+sn); }
    if (sn.StartsWith("QFX/")) { qfx++; leftover.Add("QFX "+AssetDatabase.GetAssetPath(m)+" "+sn); }
    if (sn.StartsWith("Toon/") || sn=="Shader Graphs/Water" || sn.StartsWith("Standard")) leftover.Add("OTHER "+AssetDatabase.GetAssetPath(m)+" "+sn);
  }
}
sb.AppendLine("shopFixed="+fixedN+" nulls="+nulls+" pink="+pink+" urp="+urp+" legacyPart="+legacy+" hovl="+hovl+" wfx="+wfx+" qfx="+qfx);
