var rootsDone = new System.Collections.Generic.HashSet<int>();
foreach (var t in all) {
  var root = PrefabUtility.GetNearestPrefabInstanceRoot(t.gameObject);
  if (root == null) continue;
  int id = root.GetInstanceID();
  if (!rootsDone.Add(id)) continue;
  string p = PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(root);
  bool want = false;
  foreach (var path in paths) if (path == p) want = true;
  if (!want) continue;
  PrefabUtility.ApplyPrefabInstance(root, InteractionMode.AutomatedAction);
  applied++;
}

